import {ReplayMapView,drawMinimap} from './replay-map.js';
export {atOrBefore,signalAt,sampleAt,matchingRuns,clock,timeRange,vehicleState,ARM_LABELS,SITE_LABELS,REPLAY_BASE} from './replay-data.js';
export function replayHTML(){return `
<section id="sr-scene" class="sr-scene" aria-label="Interactive study replay">
 <header class="sr-scene-header"><div class="sr-heading"><span class="sr-live-dot"></span><h1>Study replays</h1></div><button id="sr-library" class="sr-context sr-button" aria-label="Choose replay" aria-expanded="false"><span id="sr-context">Loading library…</span><span>⌄</span></button><div class="sr-header-actions"><button id="sr-compare" class="sr-button" aria-pressed="false"><span>◫</span> Compare</button><button id="sr-info" class="sr-button" aria-expanded="false" aria-label="Run details">ⓘ <span>Details</span></button><button id="sr-fullscreen" class="sr-icon" aria-label="Expand replay map" title="Expand replay map">⛶</button></div></header>
 <section id="sr-run-panel" class="sr-run-panel" role="dialog" aria-label="Choose recorded run" hidden><div class="sr-popover-heading"><b>Replay library <span>126 runs</span></b><button id="sr-library-close" class="sr-icon" aria-label="Close replay library">×</button></div><div class="sr-run-form">
 <label>Experiment<select id="sr-study" disabled><option value="ordinary">Traffic control · 48 runs</option><option value="emergency">Emergency beacon · 78 runs</option></select></label><label>Layout<select id="sr-layout" disabled>${Object.entries(SITE_LABELS).map(([k,v])=>`<option value="${k}">${k==='CORRIDOR'?'Connected corridor':k+' · '+v}</option>`).join('')}</select></label><label>Period<select id="sr-period" disabled><option value="AM">AM · 07:00–08:00</option><option value="PM">PM · 17:00–18:00</option></select></label><label>Seed<select id="sr-seed" disabled></select></label><label>Baseline<select id="sr-left" disabled></select></label><label>Displayed policy<select id="sr-right" disabled></select></label></div><p class="sr-form-note">Policies share the same demand, seed and simulated clock.<span id="sr-availability"></span></p><button id="sr-show-capture" class="sr-button sr-capture-action" hidden>Show AM vehicle capture ↗</button></section>
 <div id="sr-stage" class="sr-stage"><div id="sr-maps" class="sr-maps">${['a','b'].map((k,i)=>`<article id="sr-pane-${k}" class="sr-pane" ${i===0?'hidden':''} aria-label="${i===0?'Baseline':'Displayed'} replay map"><div id="sr-viewport-${k}" class="sr-viewport"><canvas id="sr-map-${k}" tabindex="0" aria-label="${i===0?'Baseline':'Displayed'} interactive study map. Drag to pan, scroll to zoom, arrow keys to move, plus and minus to zoom."></canvas><div class="sr-marker-layer" aria-label="Study intersections and pucks"></div><div class="sr-map-title sr-map-ui"><strong id="sr-title-${k}">—</strong><span id="sr-mini-stats-${k}"></span></div><div class="sr-scale sr-map-ui"><span id="sr-scale-${k}"></span></div></div></article>`).join('')}</div>
 <div class="sr-focus-bar" role="group" aria-label="Focus intersection"><button data-sr-focus="all">All sites</button><button data-sr-focus="J1">J1</button><button data-sr-focus="J2">J2</button><button data-sr-focus="J3">J3</button></div><div class="sr-navigation" role="group" aria-label="Map navigation"><button id="sr-zoom-in" class="sr-icon" aria-label="Zoom in" title="Zoom in">+</button><button id="sr-zoom-out" class="sr-icon" aria-label="Zoom out" title="Zoom out">−</button><span id="sr-zoom-value">1×</span><button id="sr-fit" class="sr-icon" aria-label="Fit study area" title="Fit study area">⌖</button></div><div class="sr-minimap"><canvas id="sr-minimap" tabindex="0" aria-label="Corridor minimap. Click a location to navigate."></canvas><span>Corridor overview</span></div><div id="sr-tooltip" class="sr-tooltip" role="tooltip" hidden></div><div id="sr-loading" class="sr-loading"><span class="sr-loader"></span><span id="sr-load-status" role="status">Loading recorded study…</span></div>
 <aside id="sr-details" class="sr-details" aria-label="Replay details" hidden><div class="sr-popover-heading"><b>Run details</b><button id="sr-info-close" class="sr-icon" aria-label="Close run details">×</button></div><div class="sr-detail-tabs" role="tablist" aria-label="Replay details tabs"><button role="tab" data-sr-tab="summary" aria-selected="true">Summary</button><button role="tab" data-sr-tab="events" aria-selected="false">Events</button><button role="tab" data-sr-tab="source" aria-selected="false">Source</button></div><div id="sr-detail-body" class="sr-detail-body" role="tabpanel"></div></aside></div>
 <footer class="sr-transport"><button id="sr-play" class="sr-play" disabled>▶ <span>Play</span></button><button id="sr-reset" class="sr-icon" aria-label="Restart replay" title="Restart replay" disabled>↶</button><output id="sr-clock">00:20:00</output><div class="sr-timeline"><input id="sr-scrub" type="range" min="0" max="4200" step="0.5" value="1200" aria-label="Recorded simulation time" disabled><span id="sr-end">01:10:00</span></div><select id="sr-speed" aria-label="Playback speed">${[1,5,10,20,40].map(n=>`<option value="${n}" ${n===10?'selected':''}>${n}×</option>`).join('')}</select><select id="sr-jump" aria-label="Jump to replay chapter"><option value="">Jump to…</option><option value="capture">Vehicle capture</option><option value="600">Study start</option><option value="0">Beginning</option><option value="end">End of trace</option></select></footer>
 <div class="sr-statusline"><button id="sr-source" aria-label="Replay data source">Recorded SUMO</button><div class="sr-legend"><span><i class="sr-key-car"></i>Car</span><span><i class="sr-key-bus"></i>PUV / bus</span><span><i class="sr-key-truck"></i>Truck</span><span><i class="sr-key-motorcycle"></i>Motorcycle</span><span><i class="sr-key-puck"></i>Puck</span><span><i class="sr-key-signal"></i>Signal</span></div><span class="sr-attribution">Road geometry © OpenStreetMap contributors</span></div></section>`;}
export class StudyReplay{
 constructor({state={}}={}){this.state={study:'ordinary',layout:'CORRIDOR',period:'AM',seed:7100,left:'fixed',right:'rule',focus:'J3',compare:false,...state};this.t=1200;this.rate=10;this.playing=false;this.generation=0;this.abort=new AbortController();this.dirty=true;this.infoTab='summary';this.maps={};this.lastUI=0;this.lastPaint=0;}
 el(id){return document.getElementById('sr-'+id);}
 bind(id,type,fn,extra={}){this.el(id).addEventListener(type,fn,{...extra,signal:this.abort.signal});}
 renderSoon(){this.dirty=true;}
 async mount(){try{this.bindControls();for(const k of ['a','b'])this.maps[k]=new ReplayMapView(k,{camera:()=>this.camera,move:c=>this.move(c),focus:s=>this.focus(s),inspect:(h,p)=>this.inspect(h,p),redraw:()=>this.renderSoon()});this.manifest=await jsonFile('manifest.json');if(this.abort.signal.aborted)return;for(const k of ['study','layout','period'])this.el(k).value=this.state[k];this.options();await this.load();if(this.abort.signal.aborted)return;for(const k of ['study','layout','period','seed','left','right'])this.el(k).disabled=false;this.prev=performance.now();const tick=now=>{if(this.abort.signal.aborted)return;const dt=Math.min((now-this.prev)/1000,.2);this.prev=now;if(this.playing){this.t=Math.min(this.horizon,this.t+dt*this.rate);this.dirty=true;if(this.t>=this.horizon)this.playing=false;}if(this.dirty&&now-this.lastPaint>32){this.draw();this.lastPaint=now;this.dirty=false;}this.raf=requestAnimationFrame(tick);};this.raf=requestAnimationFrame(tick);}catch(e){this.error(e);}}
 bindControls(){
  for(const k of ['study','layout','period','seed','left','right'])this.bind(k,'change',()=>{this.state[k]=this.el(k).value;if(k==='layout'){this.state.camera=null;this.state.focus=this.state.layout==='CORRIDOR'?'all':this.state.layout;}this.options(k==='study');this.load();});
  this.bind('show-capture','click',()=>{this.state.study='ordinary';this.state.period='AM';this.state.seed=7100;this.el('study').value='ordinary';this.el('period').value='AM';this.options(true);this.toggleLibrary(false);this.load();});
  this.bind('library','click',()=>this.toggleLibrary());this.bind('library-close','click',()=>this.toggleLibrary(false));this.bind('info','click',()=>this.toggleDetails());this.bind('info-close','click',()=>this.toggleDetails(false));this.bind('source','click',()=>{this.infoTab='source';this.toggleDetails(true);});this.bind('compare','click',()=>{this.state.compare=!this.state.compare;this.syncLayout();this.renderSoon();});
  this.bind('play','click',()=>{if(this.t>=this.horizon)this.t=this.playbackStart;this.playing=!this.playing;this.renderSoon();});this.bind('reset','click',()=>{this.playing=false;this.t=this.playbackStart;this.renderSoon();});this.bind('scrub','input',()=>{this.playing=false;this.t=Number(this.el('scrub').value);this.renderSoon();});this.bind('speed','change',()=>this.rate=Number(this.el('speed').value));this.bind('jump','change',()=>{const v=this.el('jump').value;if(!v)return;this.playing=false;this.t=v==='capture'?this.playbackStart:v==='end'?this.horizon:Number(v);this.el('jump').value='';this.renderSoon();});
  this.bind('zoom-in','click',()=>this.zoom(1.5));this.bind('zoom-out','click',()=>this.zoom(1/1.5));this.bind('fit','click',()=>this.focus('all'));
  document.querySelectorAll('[data-sr-focus]').forEach(b=>b.addEventListener('click',()=>this.focus(b.dataset.srFocus),{signal:this.abort.signal}));document.querySelectorAll('[data-sr-tab]').forEach(b=>b.addEventListener('click',()=>{this.infoTab=b.dataset.srTab;this.drawDetails();},{signal:this.abort.signal}));
  this.bind('minimap','pointerdown',e=>{if(!this.camera||!this.miniCamera)return;e.preventDefault();const b=e.currentTarget.getBoundingClientRect(),[x,y]=unproject(this.miniCamera,e.clientX-b.left,e.clientY-b.top,b.width,b.height);this.move({...this.camera,x,y});});this.bind('minimap','keydown',e=>{if(e.key==='Enter'||e.key==='Home'){e.preventDefault();this.focus('all');}});
  this.bind('fullscreen','click',async()=>{try{if(document.fullscreenElement===this.el('scene'))await document.exitFullscreen();else await this.el('scene').requestFullscreen();}catch{this.el('fullscreen').title='Fullscreen is unavailable in this browser';}});
  this.bind('tooltip','click',e=>{const b=e.target.closest('[data-inspector-focus]');if(b){this.focus(b.dataset.inspectorFocus);this.inspect(null,true);}if(e.target.closest('[data-inspector-close]'))this.inspect(null,true);});document.addEventListener('keydown',e=>{if(e.key==='Escape'){this.toggleLibrary(false);this.toggleDetails(false);this.inspect(null,true);}},{signal:this.abort.signal});document.addEventListener('pointerdown',e=>{if(!this.el('run-panel').hidden&&!e.target.closest('#sr-run-panel,#sr-library'))this.toggleLibrary(false);},{signal:this.abort.signal});
 }
 options(reset=false){const s=this.state,seeds=[...new Set(this.manifest.runs.filter(r=>r.study===s.study).map(r=>r.seed))];if(reset||!seeds.includes(Number(s.seed)))s.seed=seeds[0];this.el('seed').innerHTML=seeds.map(n=>`<option value="${n}">${n}</option>`).join('');this.el('seed').value=s.seed;const runs=matchingRuns(this.manifest,s),arms=[...new Set(runs.map(r=>r.arm))];if(reset||!arms.includes(s.left))s.left=arms.includes('fixed')?'fixed':arms[0];if(reset||!arms.includes(s.right))s.right=arms.includes('rule')?'rule':arms.includes('priority20')?'priority20':arms.at(-1);for(const side of ['left','right']){this.el(side).innerHTML=arms.map(a=>`<option value="${a}">${ARM_LABELS[a]}</option>`).join('');this.el(side).value=s[side];}}
 async load(){const generation=++this.generation;this.loading=true;this.playing=false;this.inspect(null,true);this.el('loading').hidden=false;this.el('loading').classList.remove('is-error');this.el('load-status').textContent='Loading recorded replay…';this.el('play').disabled=true;try{
  const matches=matchingRuns(this.manifest,this.state),a=matches.find(r=>r.arm===this.state.left),b=matches.find(r=>r.arm===this.state.right);if(!a||!b)throw Error('This selection has no saved study run.');const[g,left,right,catalog]=await Promise.all([jsonFile(this.manifest.geometry[this.state.layout]),jsonFile(a.file,true),jsonFile(b.file,true),jsonFile('motion-manifest.json')]);const motions=await Promise.all([a,b].map(m=>catalog.captures[m.id]?jsonFile(catalog.captures[m.id].file,true):null));if(generation!==this.generation||this.abort.signal.aborted)return;
  this.geometry=g;this.runs=[left,right];this.meta=[a,b];this.motions=motions;this.horizon=Math.max(a.horizon_s,b.horizon_s);this.playbackStart=motions.some(Boolean)?1200:this.state.study==='emergency'?Math.min(...[left,right].flatMap(r=>r.probe_positions.slice(0,1).map(p=>p.time_s))):600;if(!Number.isFinite(this.playbackStart))this.playbackStart=1800;this.t=this.playbackStart;const dims=this.dimensions();this.referenceScale=fitSignals(g,'all',...dims).scale;if(!this.state.camera){const selected=g.signals.some(s=>s.site===this.state.focus)?this.state.focus:'all';this.state.focus=selected;this.camera=fitSignals(g,selected,...dims);}else this.camera=constrainCamera(this.state.camera,g,...dims);this.state.camera=this.camera;
  this.el('availability').textContent=motions.some(Boolean)?'Vehicle motion available · AM / 7100, 20–40 min.':this.state.study==='ordinary'?'Controller trace only for this run.':'Original emergency probe positions · 1 Hz.';this.el('show-capture').hidden=this.state.study!=='ordinary'||motions.some(Boolean);this.loading=false;this.el('loading').hidden=true;this.el('play').disabled=false;this.el('reset').disabled=false;this.el('scrub').disabled=false;this.el('scrub').max=this.horizon;this.el('context').textContent=`${this.state.layout==='CORRIDOR'?'Connected corridor':this.state.layout} · ${this.state.period} · ${this.state.seed}`;for(const[i,k]of ['a','b'].entries())this.el('title-'+k).textContent=ARM_LABELS[this.meta[i].arm];this.syncLayout();this.draw();this.renderSoon();
 }catch(e){if(generation===this.generation)this.error(e);}}
 error(e){if(this.abort.signal.aborted)return;this.loading=false;this.el('loading').hidden=false;this.el('load-status').textContent=e.message;this.el('loading').classList.add('is-error');}
 dimensions(){const e=this.el('viewport-b');return[Math.max(200,e.clientWidth),Math.max(250,e.clientHeight)];}
 syncLayout(){this.el('scene').dataset.compare=String(this.state.compare);this.el('pane-a').hidden=!this.state.compare;this.el('compare').setAttribute('aria-pressed',String(this.state.compare));}
 move(c){if(!this.geometry)return;this.camera=constrainCamera(c,this.geometry,...this.dimensions());this.state.camera=this.camera;this.state.focus=null;this.renderSoon();}
 focus(site){if(!this.geometry)return;this.state.focus=site;this.camera=fitSignals(this.geometry,site,...this.dimensions());this.state.camera=this.camera;this.inspect(null,true);this.renderSoon();}
 zoom(factor){if(!this.camera)return;const[w,h]=this.dimensions();this.move(zoomCamera(this.camera,factor,[w/2,h/2],w,h));}
 toggleLibrary(force){const open=force??this.el('run-panel').hidden;this.el('run-panel').hidden=!open;this.el('library').setAttribute('aria-expanded',String(open));if(open){this.toggleDetails(false);this.inspect(null,true);this.el('study').focus();}}
 toggleDetails(force){const open=force??this.el('details').hidden;this.el('details').hidden=!open;this.el('info').setAttribute('aria-expanded',String(open));if(open){this.toggleLibrary(false);this.inspect(null,true);this.drawDetails();}}
 inspect(hit,pinned=false){if(!pinned&&this.inspector?.pinned)return;if(!hit){this.inspector=null;this.el('tooltip').hidden=true;return;}this.inspector={...hit,pinned};this.drawInspector(true);}
 drawInspector(force=false){const hit=this.inspector;if(!hit||!this.geometry||!this.runs)return;const index=hit.key==='a'?0:1,r=this.runs[index],d=hit.data,viewport=this.el('viewport-'+hit.key),box=this.el('tooltip');if(viewport.clientWidth<1){this.inspect(null,true);return;}const hash=[hit.kind,d.id||d.site||d.lane,Math.floor(this.t),hit.pinned].join('/');if(force||hash!==this.inspectorHash){let heading='',body='',tag='';
  if(hit.kind==='detector'){heading=d.id;tag='PUCK / STUDY POSITION';const role=d.roles.includes('upstream_5')?'5 m upstream':d.roles.includes('upstream_30')?'30 m upstream':d.roles.includes('upstream_60')?'60 m upstream':'Downstream exit counter';body=`<p>${esc(d.site)} · ${role}</p><div class="sr-inspector-grid"><span>Actual chainage</span><b>${Number(d.actual_chainage_m).toFixed(1)} m</b><span>Occupancy</span><b class="sr-muted">Not recorded</b></div>${d.shifted?'<p class="sr-muted">Offset shifted in the study catalog.</p>':''}<details><summary>Geometry details</summary><p>Lane <code>${esc(d.lane)}</code></p><p>Model x ${d.x.toFixed(3)} · y ${d.y.toFixed(3)} m</p></details>`;}
  else if(hit.kind==='junction'){const s=signalAt(r,d.site,this.t),sample=sampleAt(r,d.site,this.t);heading=SITE_LABELS[d.site];tag=d.site+' / INTERSECTION';body=`<p class="sr-phase"><i style="background:${s.aspect==='green'?'#4ee2a8':s.aspect==='yellow'?'#ffc35c':'#fa6679'}"></i>Stage ${s.stage+1} · ${s.aspect.replaceAll('_',' ')}</p><div class="sr-inspector-grid"><span>Model pucks</span><b>${this.geometry.detectors.filter(p=>p.site===d.site).length}</b>${sample?`<span>Boundary entries / exits</span><b>${sample.boundary_entries} / ${sample.boundary_exits}</b><span>Raw inventory</span><b>${sample.stock_raw}</b>`:''}</div><p class="sr-muted">${sample?'Sample '+clock(sample.time_s)+' · ':''}Model signal reference, not a surveyed cabinet.</p>${hit.pinned?`<button class="sr-button sr-focus-action" data-inspector-focus="${d.site}">Focus intersection ↗</button>`:''}`;}
  else if(hit.kind==='signal'){heading='Model signal · '+d.site;tag='NATIVE LANE SIGNAL';body=`<p class="sr-phase">${d.aspect==='g'?'Green':d.aspect==='y'?'Yellow':'Red'}</p><p>Lane <code>${esc(d.lane)}</code></p><p class="sr-muted">Native movement ${d.links.join(' / ')}. Indicator placement is schematic.</p>`;}
  else if(hit.kind==='probe'){heading='Emergency probe';tag='ORIGINAL 1 HZ POSITIONS';body=`<p>${Number(d.speed_m_s*3.6).toFixed(1)} km/h · sample ${clock(d.time_s)}</p><p class="sr-muted">Original simulated probe, not a live vehicle beacon.</p>`;}
  else{heading=d.type.replaceAll('_',' ').toLowerCase();tag='VEHICLE / MATCHED CAPTURE';body=`<p>${esc(d.id)}</p><p>${d.length} m long · ${d.width} m wide</p><p class="sr-muted">Observer-only reproduction matched to the original controller and sensor traces.</p>`;}
  box.innerHTML=`<div class="sr-inspector-tag">${esc(tag)}${hit.pinned?'<button class="sr-icon" data-inspector-close aria-label="Close map inspector">×</button>':''}</div><h3>${esc(heading)}</h3>${body}${!hit.pinned?'<small class="sr-inspector-hint">Click to keep open</small>':''}`;box.classList.toggle('is-pinned',hit.pinned);box.setAttribute('role',hit.pinned?'dialog':'tooltip');box.setAttribute('aria-label',heading);this.inspectorHash=hash;
 }box.hidden=false;const stage=this.el('stage').getBoundingClientRect(),b=viewport.getBoundingClientRect(),[x,y]=project(this.camera,d.x,d.y,b.width,b.height),w=box.offsetWidth,h=box.offsetHeight;let left=b.left-stage.left+x+17,top=b.top-stage.top+y-h/2;if(left+w>stage.width-12)left=b.left-stage.left+x-w-17;box.style.left=Math.max(10,Math.min(stage.width-w-10,left))+'px';box.style.top=Math.max(10,Math.min(stage.height-h-10,top))+'px';}
 draw(){if(!this.runs||!this.camera||this.abort.signal.aborted)return;for(const[i,k]of ['a','b'].entries())if(i===1||this.state.compare)this.maps[k].draw(this.geometry,this.runs[i],Math.min(this.t,this.meta[i].horizon_s),this.motions[i]);this.el('clock').textContent=clock(this.t);this.el('scrub').value=this.t;this.el('end').textContent=clock(this.horizon);this.el('play').innerHTML=this.playing?'Ⅱ <span>Pause</span>':'▶ <span>Play</span>';this.el('zoom-value').textContent=(this.camera.scale/this.referenceScale).toFixed(1)+'×';document.querySelectorAll('[data-sr-focus]').forEach(b=>{b.hidden=b.dataset.srFocus!=='all'&&!this.geometry.signals.some(s=>s.site===b.dataset.srFocus);b.setAttribute('aria-pressed',String(b.dataset.srFocus===this.state.focus));});const[w,h]=this.dimensions();this.miniCamera=drawMinimap(this.el('minimap'),this.geometry,this.camera,w,h);for(const[i,k]of ['a','b'].entries()){const motion=this.motions[i],active=motion&&this.t>=1200&&this.t<=2400;this.el('mini-stats-'+k).textContent=active?`${this.maps[k].last?.vehicleHits.length||0} vehicles in view`:this.state.study==='emergency'?'Original probe trace':'Recorded controller trace';const m=niceDistance(85/this.camera.scale),bar=this.el('scale-'+k);bar.style.width=Math.round(m*this.camera.scale)+'px';bar.textContent=m+' m';}this.el('source').textContent=this.motions[1]&&this.t>=1200&&this.t<=2400?'◉ Matched vehicle capture':this.state.study==='emergency'?'◉ Original probe replay':'◉ Recorded controller trace';if(performance.now()-this.lastUI>350){this.drawDetails();this.lastUI=performance.now();}this.drawInspector();}
 drawDetails(){if(this.el('details').hidden||!this.runs)return;const hash=[this.infoTab,...this.meta.map(m=>m.id),this.infoTab==='events'?Math.floor(this.t):'static'].join('/');if(hash===this.detailHash)return;this.detailHash=hash;document.querySelectorAll('[data-sr-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.srTab===this.infoTab)));let html='';
  if(this.infoTab==='summary'){html=`<p class="sr-detail-subtitle">${esc(SITE_LABELS[this.state.layout])}<br>${this.state.period} · seed ${this.state.seed} · demand ×1.00</p>`;for(const m of this.meta){const d=m.metrics;html+=`<section class="sr-result-card"><h3>${esc(ARM_LABELS[m.arm])}</h3><code>${esc(m.id)}</code>`;if(this.state.study==='ordinary')html+=`<span>Final study cohort · 4,200 s cutoff</span><strong>${d.study_cohort_completed.toLocaleString()} <small>/ ${d.study_cohort_scheduled.toLocaleString()} completed</small></strong><p>${d.study_cohort_active} active · ${d.study_cohort_uninserted.toLocaleString()} uninserted</p><p>Accumulated time ${d.study_mean_accumulated_s.toFixed(1)} s/vehicle</p>`;else html+=`<span>Original emergency result</span><strong>${d.probe.dispatch_to_arrival_s.toFixed(1)} <small>s dispatch to arrival</small></strong><p>${d.probe.duration.toFixed(1)} s on road · ${d.probe.departDelay.toFixed(1)} s insertion delay</p>`;html+='</section>';}html+='<a class="sr-text-link" href="./study/">Full results & methods ↗</a>';}
  else if(this.infoTab==='events'){for(const[i,r]of this.runs.entries()){const events=[...Object.entries(r.supervisor_events).flatMap(([site,rows])=>rows.map(e=>({...e,site,t:e.time}))),...r.beacon_events.map(e=>({...e,t:e.time_s}))].filter(e=>e.t<=this.t).sort((a,b)=>b.t-a.t).slice(0,9);html+=`<h3>${esc(ARM_LABELS[this.meta[i].arm])}</h3>`+events.map(e=>`<div class="sr-event"><code>${clock(e.t)}</code><p><b>${esc(e.site||'PROBE')} · ${esc(e.kind||e.aspect)}</b><span>${esc(e.reason||'')}</span></p></div>`).join('');}}
  else{html='<h3>What is being replayed?</h3><p>All 126 saved runs retain exact signal transitions and 5 s aggregate sensor traces. Emergency positions are the original 1 Hz probe records.</p><p>Eight matched AM/seed-7100 captures add ordinary vehicle motion from 1,200–2,400 s. They are observer-only reproductions checked against the complete archived sensor traces, transitions and core final counts.</p><p>Other periods/seeds show their saved controller traces. Individual puck occupancy and hardware health were not recorded. Neutral puck symbols mark catalogued positions.</p><h3>Geometry</h3><p>The frozen study network uses native SUMO lane, detector and signal IDs. Signal-head placement is schematic. Cabinet locations and editable installation plans are separate.</p><p>Motor-only reconstructed simulation; no field validation or trained neural policy is claimed.</p>';for(const r of this.runs)html+=`<details><summary>${esc(r.id)} · source hash</summary><code>${esc(r.provenance.archive_sha256)}</code></details>`;}this.el('detail-body').innerHTML=html;
 }
 destroy(){this.abort.abort();cancelAnimationFrame(this.raf);for(const m of Object.values(this.maps))m.destroy();this.playing=false;}
}
function niceDistance(n){const p=10**Math.floor(Math.log10(n)),d=n/p;return(d>=5?5:d>=2?2:1)*p;}
